this.host=host;host.innerHTML='<canvas class="architecture-canvas" tabindex="0" aria-label="Infinite architecture. Drag to pan, scroll to zoom, arrow keys to move, plus and minus to zoom."></canvas><div class="world-controls"><button type="button" aria-label="Zoom in">+</button><button type="button" aria-label="Zoom out">−</button></div>';
